mapper.select:
SELECT
WHERE t.deleted = 0
ORDER BY t.submit_time DESC, t.id DESC LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE volunteer_appeal
record_id = #{a.recordId}, blacklist_id = #{a.blacklistId}, reason = #{a.reason}, submit_time = #{a.submitTime}, accept_org = #{a.acceptOrg}, within_window = #{a.withinWindow}, status = #{a.status}, ruling = #{a.ruling}, ruler_id = #{a.rulerId}, ruling_time = #{a.rulingTime}, updated_at = NOW()
WHERE id = #{a.id} AND deleted = 0 AND status = #{fromStatus}

mapper.select:
SELECT COUNT(*)
FROM volunteer_appeal t
WHERE t.user_id = #{userId}
  AND t.status = 'pending'
  AND t.deleted = 0
AND t.record_id = #{recordId}
AND t.blacklist_id = #{blacklistId}
